import{_ as r,o as t,c as s,ah as n}from"./chunks/framework.C-FRNfAJ.js";const m=JSON.parse('{"title":"Recruter des profils certifiés","description":"","frontmatter":{"layout":"doc"},"headers":[],"relativePath":"guide/entreprises/recrutement.md","filePath":"src/guide/entreprises/recrutement.md"}'),o={name:"guide/entreprises/recrutement.md"};function a(i,e,l,u,p,c){return t(),s("div",null,[...e[0]||(e[0]=[n('<h1 id="recruter-des-profils-certifies" tabindex="-1">Recruter des profils certifiés <a class="header-anchor" href="#recruter-des-profils-certifies" aria-label="Permalink to &quot;Recruter des profils certifiés&quot;">​</a></h1><p>NextBoxx met en relation les entreprises avec ses <strong>apprenants certifiés</strong> qui le souhaitent, pour un stage, une alternance, une mission ou un recrutement.</p><h2 id="deposer-une-demande" tabindex="-1">Déposer une demande <a class="header-anchor" href="#deposer-une-demande" aria-label="Permalink to &quot;Déposer une demande&quot;">​</a></h2><p>Dans <strong>Parcours → Mes demandes entreprise → Nouvelle demande</strong>, choisissez le type :</p><table tabindex="0"><thead><tr><th>Type</th><th>Champs propres</th></tr></thead><tbody><tr><td><strong>Mise en relation</strong></td><td>Stage, alternance ou mission ; compétences recherchées ; début souhaité ; durée en mois ; lieu</td></tr><tr><td><strong>Recrutement</strong></td><td>Intitulé du poste ; contrat (CDI ou CDD) ; lieu ; salaire indicatif (facultatif) ; date d&#39;embauche souhaitée</td></tr></tbody></table><p>Dans les deux cas, indiquez aussi la raison sociale, le <strong>nombre de profils recherchés</strong> (de 1 à 20), un programme visé (facultatif), un message, et si vous souhaitez l&#39;<strong>accompagnement</strong> : NextBoxx suit alors l&#39;intégration de chaque profil retenu, contre un forfait supplémentaire par profil.</p><p>L&#39;entrée « Mes demandes entreprise » est visible pour tout compte personne, même avant la première demande. Le Chargé de partenariats est prévenu de votre demande.</p><h2 id="les-profils-proposes" tabindex="-1">Les profils proposés <a class="header-anchor" href="#les-profils-proposes" aria-label="Permalink to &quot;Les profils proposés&quot;">​</a></h2><p>Le Chargé de partenariats vous propose, en une ou plusieurs fois, des profils <strong>certifiés et visibles</strong> : des apprenants qui ont choisi de se rendre visibles des entreprises. Pour chacun, vous voyez d&#39;abord son <strong>prénom et l&#39;initiale de son nom</strong>, ses <strong>certificats</strong> (programme, mention, date) et sa <strong>présentation</strong>.</p><p>Pour chaque profil, vous choisissez <strong>Retenir</strong> ou <strong>Écarter</strong> (le Chargé peut aussi l&#39;enregistrer pour vous).</p><ul><li>Un profil <strong>retenu</strong> vous révèle le <strong>nom, l&#39;adresse e-mail, le téléphone et le CV</strong> de la personne, et elle en est prévenue.</li><li>Un profil qui se retire (parce que la personne se masque) quitte les propositions en attente ; un profil déjà retenu reste partagé.</li></ul><h2 id="la-confirmation-et-la-facture" tabindex="-1">La confirmation et la facture <a class="header-anchor" href="#la-confirmation-et-la-facture" aria-label="Permalink to &quot;La confirmation et la facture&quot;">​</a></h2><p>Dès qu&#39;au moins un profil est retenu, le Chargé confirme la <strong>mise en relation</strong>. Une facture est alors émise à votre raison sociale, <strong>échue à 30 jours</strong>. Elle compte, <strong>par profil retenu</strong> :</p><ul><li>le forfait de mise en relation ;</li><li>le forfait d&#39;accompagnement, si vous l&#39;avez demandé.</li></ul><p>La demande passe à « Acceptée » et les profils encore en attente sont clos comme non retenus. Si aucun profil ne convient, le Chargé clôt la demande, sans facture.</p><p>Les rappels et la relance de cette facture suivent la chronologie habituelle, <strong>sans suspension</strong> d&#39;accès.</p>',16)])])}const f=r(o,[["render",a]]);export{m as __pageData,f as default};
